-- ============================================================================
-- Migrasi Tahap 7 (1/2): Kolom Metadata Sumber & Impor Idempotent 128 Pembangkit Nyata
-- Sumber: data/staging/{geothermal,wind,hydro,solar,bioenergy}.csv (terverifikasi SHA-256)
-- Aturan: Tanpa mengubah/membulatkan nilai CSV, verified_at = NULL, is_demo = false.
-- ============================================================================

begin;

-- 1. Pastikan kolom metadata Tahap 7A tersedia & description boleh NULL
alter table public.power_plants
  alter column description drop not null;

alter table public.power_plants
  add column if not exists source_notes text,
  add column if not exists coordinate_precision text not null default 'exact'
    check (coordinate_precision in ('exact', 'approximate')),
  add column if not exists external_ref text,
  add column if not exists data_as_of text;

-- 2. Kunci unik untuk ON CONFLICT: (category_id, name) + partial unique index external_ref
do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'power_plants_category_id_name_unique'
      and conrelid = 'public.power_plants'::regclass
  ) then
    alter table public.power_plants
      add constraint power_plants_category_id_name_unique unique (category_id, name);
  end if;
end $$;

create unique index if not exists idx_power_plants_external_ref_unique
  on public.power_plants (external_ref)
  where external_ref is not null;

-- 3. Perbarui RPC nearby_plants agar menyertakan kolom metadata baru
drop function if exists public.nearby_plants(double precision, double precision, integer, text);

create or replace function public.nearby_plants(
  lat double precision,
  lng double precision,
  radius_m integer,
  category_slug text default null
)
returns table (
  id uuid,
  category_id uuid,
  category_slug text,
  category_name text,
  category_short_code text,
  name text,
  description text,
  province text,
  city text,
  latitude double precision,
  longitude double precision,
  coordinate_precision text,
  capacity_mw numeric,
  operational_status text,
  operator_name text,
  image_url text,
  source_url text,
  source_notes text,
  external_ref text,
  data_as_of text,
  verified_at timestamptz,
  is_demo boolean,
  is_published boolean,
  created_at timestamptz,
  updated_at timestamptz,
  distance_meters double precision
)
language sql
stable
set search_path = public, extensions
as $$
  select
    p.id,
    p.category_id,
    c.slug as category_slug,
    c.name as category_name,
    c.short_code as category_short_code,
    p.name,
    p.description,
    p.province,
    p.city,
    p.latitude,
    p.longitude,
    p.coordinate_precision,
    p.capacity_mw,
    p.operational_status,
    p.operator_name,
    p.image_url,
    p.source_url,
    p.source_notes,
    p.external_ref,
    p.data_as_of,
    p.verified_at,
    p.is_demo,
    p.is_published,
    p.created_at,
    p.updated_at,
    ST_Distance(
      p.geog,
      ST_SetSRID(ST_MakePoint(lng, lat), 4326)::geography
    ) as distance_meters
  from public.power_plants p
  join public.energy_categories c on c.id = p.category_id
  where p.is_published = true
    and p.is_demo = false
    and ST_DWithin(
      p.geog,
      ST_SetSRID(ST_MakePoint(lng, lat), 4326)::geography,
      radius_m
    )
    and (
      nearby_plants.category_slug is null
      or c.slug = nearby_plants.category_slug
    )
  order by distance_meters asc;
$$;

