insert into public.power_plants (
  category_id, name, description, province, city,
  latitude, longitude, coordinate_precision, capacity_mw,
  operational_status, operator_name, source_url, source_notes,
  external_ref, data_as_of, verified_at, is_demo, is_published
)
select
  c.id,
  r.name,
  r.description,
  r.province,
  r.city,
  r.latitude,
  r.longitude,
  r.coordinate_precision,
  r.capacity_mw,
  r.operational_status,
  r.operator_name,
  r.source_url,
  r.source_notes,
  r.external_ref,
  r.data_as_of,
  null::timestamptz as verified_at,
  false as is_demo,
  true as is_published
from raw_staging r
inner join public.energy_categories c on c.slug = r.category_slug
on conflict (category_id, name) do update
set
  description = excluded.description,
  province = excluded.province,
  city = excluded.city,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  coordinate_precision = excluded.coordinate_precision,
  capacity_mw = excluded.capacity_mw,
  operational_status = excluded.operational_status,
  operator_name = excluded.operator_name,
  source_url = excluded.source_url,
  source_notes = excluded.source_notes,
  external_ref = excluded.external_ref,
  data_as_of = excluded.data_as_of,
  verified_at = null,
  is_demo = false,
  is_published = true,
  updated_at = now();

commit;

-- ============================================================================
-- QUERY VERIFIKASI PASCA-IMPOR
-- Harus cocok dengan: geothermal 34 (18/3/13), wind 6 (2/0/4), hydro 55 (35/5/15),
-- solar 11 (8/1/2), bioenergy 22 (22/0/0); TOTAL 128 (85/9/34);
-- missing_source_url = 0; out_of_indonesia_bbox = 0.
-- ============================================================================
select
  coalesce(c.slug, 'TOTAL') as category_slug,
  count(*)::int as total_rows,
  count(*) filter (where p.operational_status = 'operating')::int as operating_count,
  count(*) filter (where p.operational_status = 'construction')::int as construction_count,
  count(*) filter (where p.operational_status = 'planned')::int as planned_count,
  count(*) filter (where p.source_url is null or btrim(p.source_url) = '')::int as missing_source_url,
  count(*) filter (
    where p.latitude not between -11.5 and 6.5
       or p.longitude not between 94.5 and 141.5
  )::int as out_of_indonesia_bbox
from public.power_plants p
join public.energy_categories c on c.id = p.category_id
where p.is_demo = false
group by rollup(c.slug)
order by case c.slug
  when 'geothermal' then 1
  when 'wind' then 2
  when 'hydro' then 3
  when 'solar' then 4
  when 'bioenergy' then 5
  else 6
end;
